using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _sut = null!;

    [TestInitialize]
    public void Setup() => _sut = new ShoppingCart();

    #region AddItem

    [TestMethod]
    [DataRow("SKU-1", 1, 9.99, DisplayName = "Single item")]
    [DataRow("SKU-2", 5, 2.50, DisplayName = "Multiple quantity")]
    public void AddItem_ValidInputs_AddsItemToCart(string sku, int qty, double price)
    {
        _sut.AddItem(sku, qty, (decimal)price);

        Assert.IsTrue(_sut.Items.ContainsKey(sku));
        Assert.AreEqual(qty, _sut.Items[sku].Quantity);
        Assert.AreEqual((decimal)price, _sut.Items[sku].Price);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_CombinesQuantity()
    {
        _sut.AddItem("SKU-A", 2, 10m);
        _sut.AddItem("SKU-A", 3, 10m);

        Assert.AreEqual(5, _sut.Items["SKU-A"].Quantity);
    }

    [TestMethod]
    [DataRow(null, DisplayName = "Null SKU")]
    [DataRow("", DisplayName = "Empty SKU")]
    [DataRow("   ", DisplayName = "Whitespace SKU")]
    public void AddItem_InvalidSku_ThrowsArgumentException(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(() => _sut.AddItem(sku!, 1, 5m));
    }

    [TestMethod]
    [DataRow(0, DisplayName = "Zero quantity")]
    [DataRow(-1, DisplayName = "Negative quantity")]
    public void AddItem_InvalidQuantity_ThrowsArgumentOutOfRangeException(int qty)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _sut.AddItem("SKU", qty, 5m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_ThrowsArgumentOutOfRangeException()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _sut.AddItem("SKU", 1, -1m));
    }

    #endregion

    #region RemoveItem

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _sut.AddItem("SKU-1", 2, 10m);

        _sut.RemoveItem("SKU-1");

        Assert.AreEqual(0, _sut.Items.Count);
    }

    [TestMethod]
    public void RemoveItem_NonExistentItem_ThrowsKeyNotFoundException()
    {
        Assert.ThrowsException<KeyNotFoundException>(() => _sut.RemoveItem("MISSING"));
    }

    [TestMethod]
    [DataRow(null, DisplayName = "Null SKU")]
    [DataRow("", DisplayName = "Empty SKU")]
    public void RemoveItem_InvalidSku_ThrowsArgumentException(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(() => _sut.RemoveItem(sku!));
    }

    #endregion

    #region CalculateTotal

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsCorrectTotal()
    {
        _sut.AddItem("SKU-1", 3, 10.00m);

        Assert.AreEqual(30.00m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_SumsAll()
    {
        _sut.AddItem("A", 2, 5.00m);  // 10
        _sut.AddItem("B", 1, 7.50m);  //  7.50

        Assert.AreEqual(17.50m, _sut.CalculateTotal());
    }

    #endregion

    #region ApplyCoupon

    [TestMethod]
    public void ApplyCoupon_SAVE10_Applies10PercentDiscount()
    {
        _sut.AddItem("SKU-1", 1, 100m);
        _sut.ApplyCoupon("SAVE10");

        Assert.AreEqual(90m, _sut.CalculateTotal());
        Assert.AreEqual("SAVE10", _sut.AppliedCoupon);
    }

    [TestMethod]
    public void ApplyCoupon_HALF_Applies50PercentDiscount()
    {
        _sut.AddItem("SKU-1", 2, 20m);
        _sut.ApplyCoupon("HALF");

        Assert.AreEqual(20m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _sut.ApplyCoupon("BOGUS"));
    }

    [TestMethod]
    [DataRow(null, DisplayName = "Null code")]
    [DataRow("", DisplayName = "Empty code")]
    public void ApplyCoupon_NullOrEmpty_ThrowsArgumentException(string? code)
    {
        Assert.ThrowsException<ArgumentException>(() => _sut.ApplyCoupon(code!));
    }

    [TestMethod]
    public void CalculateTotal_NoCoupon_ReturnsFullPrice()
    {
        _sut.AddItem("SKU-1", 1, 50m);

        Assert.AreEqual(50m, _sut.CalculateTotal());
        Assert.IsNull(_sut.AppliedCoupon);
    }

    #endregion
}

